export interface Prototype<T> {
  clone(): T;
}

export class ServiceConfiguration implements Prototype<ServiceConfiguration> {
  public serviceName: string;
  public timeoutMs: number;
  public headers: Map<string, string>;
  public endpoints: string[];

  constructor(serviceName: string, timeoutMs: number, headers: Map<string, string>, endpoints: string[]) {
    this.serviceName = serviceName;
    this.timeoutMs = timeoutMs;
    this.headers = new Map(headers);
    this.endpoints = [...endpoints];
  }

  // Deep Clone Implementation
  public clone(): ServiceConfiguration {
    // 1. Primitives copied by value
    // 2. Collections deep-copied to prevent shared state corruption
    const clonedHeaders = new Map(this.headers);
    const clonedEndpoints = [...this.endpoints];

    return new ServiceConfiguration(
      this.serviceName,
      this.timeoutMs,
      clonedHeaders,
      clonedEndpoints
    );
  }
}

// Thread-Safe Centralized Prototype Registry
export class ConfigurationRegistry {
  private static prototypes = new Map<string, Prototype<any>>();

  public static register(key: string, prototype: Prototype<any>): void {
    this.prototypes.set(key, prototype);
  }

  public static create<T>(key: string): T {
    const prototype = this.prototypes.get(key);
    if (!prototype) {
      throw new Error(`Prototype with key '${key}' not found in registry`);
    }
    return prototype.clone() as T;
  }
}
